(async()=>{'use strict';const $=s=>document.querySelector(s),sources=['scenes.json','additional-scenes.json','../marker/final-selection.json'],[a,b,selection]=await Promise.all(sources.map(async p=>(await fetch(p,{cache:'no-store'})).json()));let output=null;const policy=await(await fetch('policy.json')).json();const scenes=[...a,...b],controls=[...SpaceFoxM.controls(),...selection.candidates];
$('#runControlAudit').onclick=async()=>{$('#runControlAudit').disabled=true;const rows=[];try{for(const c of controls)for(const s of scenes){$('#status').textContent=`Контроль ${c.control?c.base.id:c.id} · ${s.id} · ${rows.length+1}/140`;const face=SpaceFoxMR.render(c,s);$('#bed').replaceChildren(face);rows.push(await SpaceFoxCM.measure(face,{id:c.control?c.base.id:c.id,control:true},s,policy));await new Promise(requestAnimationFrame);}const sourceSHA256={};for(const file of ['metrics.js','recheck.js','recheck.html','policy.json','scenes.json','additional-scenes.json']){const bytes=await(await fetch(file,{cache:'no-store'})).arrayBuffer();sourceSHA256['prototype/composition/'+file]=[...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(b=>b.toString(16).padStart(2,'0')).join('');}output={metricVersion:3,sourceSHA256,scenes,controls:controls.map(c=>c.control?c.base.id:c.id),observations:rows,scope:'Actual browser re-observation of ten controls only; no new candidate run.',completedAt:new Date().toISOString()};$('#status').textContent='Готово:140 контрольных наблюдений, формат RGB/RGBA учтён.';$('#exportControlAudit').disabled=false;}catch(e){$('#status').textContent='ОШИБКА: '+e.message;throw e;}finally{$('#bed').replaceChildren();$('#runControlAudit').disabled=false;}};
$('#exportControlAudit').onclick=()=>{const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([JSON.stringify(output)],{type:'application/json'}));link.download='composition-controls-v3.json';link.click();};await Promise.all(["600 80px 'Roboto Condensed'","600 80px 'Barlow Condensed'","600 80px 'Saira Condensed'","500 21px 'Noto Sans'"].map(f=>document.fonts.load(f,'Россия USA')));await document.fonts.ready;})();
